  153	  private loadOrProvisionSeed(): Buffer {
  154	    const record = this.db.prepare("SELECT value FROM wallet_metadata WHERE key = 'encrypted_seed'").get() as
  155	      | { value: Uint8Array }
  156	      | undefined;
  157	    if (record) {
  158	      try {
  159	        const seed = decryptSeed(Buffer.from(record.value), this.config.walletEncryptionKey);
  160	        if (seed.length !== 64) throw new Error("Longitud de seed inválida");
  161	        return seed;
  162	      } catch {
  163	        throw new Error("INTERNAL_ERROR: no se pudo descifrar o autenticar el seed custodial");
  164	      }
  165	    }
  166	
  167	    const assignment = this.db.prepare("SELECT 1 AS present FROM deposit_addresses LIMIT 1").get();
  168	    if (assignment) {
  169	      throw new Error("INTERNAL_ERROR: hay asignaciones persistidas pero falta el seed custodial");
  170	    }
  171	
  172	    let seed: Buffer;
  173	    if (this.config.hdMnemonic !== undefined) {
  174	      const mnemonic = validateProjectMnemonic(this.config.hdMnemonic);
  175	      seed = mnemonicToSeed(mnemonic, this.config.hdMnemonicPassphrase);
  176	    } else {
  177	      seed = generateProjectSeed(this.config.hdMnemonicPassphrase).seed;
  178	    }
  179	    const encrypted = encryptSeed(seed, this.config.walletEncryptionKey);
  180	    this.transaction(() => {
  181	      this.db.prepare("INSERT INTO wallet_metadata (key, value) VALUES ('encrypted_seed', ?)").run(encrypted);
  182	      const persisted = this.db.prepare(
  183	        "SELECT value FROM wallet_metadata WHERE key = 'encrypted_seed'",
  184	      ).get() as { value: Uint8Array } | undefined;
  185	      if (!persisted) throw new Error("No se pudo releer el seed cifrado");
  186	      const verified = decryptSeed(Buffer.from(persisted.value), this.config.walletEncryptionKey);
  187	      if (verified.length !== seed.length || !verified.equals(seed)) {
  188	        throw new Error("No se pudo verificar el seed cifrado");
  189	      }
  190	    });
  191	    return seed;
  192	  }
