 48	  }
 49	  if (!("email" in value)) issues.push({ field: "email", message: "Campo requerido" });
 50	  else if (typeof value.email !== "string") issues.push({ field: "email", message: "Debe ser string" });
 51	  if (!("password" in value)) issues.push({ field: "password", message: "Campo requerido" });
 52	  else if (typeof value.password !== "string") {
 53	    issues.push({ field: "password", message: "Debe ser string" });
 54	  }
 55	  if (exactFields) {
 56	    for (const field of Object.keys(value)) {
 57	      if (field !== "email" && field !== "password") {
 58	        issues.push({ field, message: "Campo desconocido" });
 59	      }
 60	    }
 61	  }
 62	  if (issues.length > 0) throw validationError(issues);
