111	  app.setErrorHandler((error, _request, reply) => {
112	    const request = _request;
113	    if (request.pendingPublicRateLimit) {
114	      const retryAfterSeconds = request.pendingPublicRateLimit.retryAfterSeconds;
115	      const apiError = new ApiError("RATE_LIMITED", { retryAfterSeconds });
116	      reply.header("Retry-After", String(retryAfterSeconds));
117	      reply.status(apiError.status).send(apiError.toBody());
118	      return;
119	    }
120	    if (error instanceof ApiError) {
121	      reply.status(error.status).send(error.toBody());
122	      return;
123	    }
124	    const fastifyError = error as Error & { code?: string; statusCode?: number };
125	    if (
126	      fastifyError.code === "FST_ERR_CTP_INVALID_MEDIA_TYPE" ||
127	      fastifyError.code === "FST_ERR_CTP_EMPTY_JSON_BODY" ||
128	      fastifyError.code === "FST_ERR_CTP_BODY_TOO_LARGE" ||
129	      fastifyError.statusCode === 400
130	    ) {
131	      const apiError = validationError([{ field: "body", message: "JSON inválido o Content-Type no soportado" }]);
132	      reply.status(apiError.status).send(apiError.toBody());
133	      return;
134	    }
