136	    reply.status(apiError.status).send(apiError.toBody());
137	  });
138	
139	  app.setNotFoundHandler((request, reply) => {
140	    const path = request.url.split("?", 1)[0] ?? request.url;
141	    const allowed = KNOWN_ROUTES[path];
