150	  const publicRateLimitCheck = (kind: "register" | "login", rateConfig: RateLimitConfig | undefined) =>
151	    async (request: FastifyRequest): Promise<void> => {
152	      if (!rateConfig) return;
153	      const result = publicLimiter.check(`${kind}:${request.ip}`, rateConfig);
154	      if (result.limited) {
155	        request.pendingPublicRateLimit = { kind, retryAfterSeconds: result.retryAfterSeconds };
156	      }
157	    };
158	
159	  const enforcePublicRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
160	    const pending = request.pendingPublicRateLimit;
161	    if (!pending) return;
162	    if (pending.kind === "login") {
163	      const email = isRecord(request.body) && typeof request.body.email === "string"
