169	  };
170	
171	  app.post(
172	    "/api/v1/auth/register",
173	    {
174	      onRequest: publicRateLimitCheck("register", config.registerRateLimit),
175	      preValidation: enforcePublicRateLimit,
176	    },
177	    async (request, reply) => {
