207	
208	  const protectedRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
209	    const account = request.authenticatedAccount;
210	    if (!account) throw new ApiError("UNAUTHENTICATED");
211	    const result = protectedLimiter.check(
212	      `${account.account_id}:${request.routeOptions.url}`,
213	      { max: 60, windowSeconds: 60 },
