243	        network: NETWORK,
244	        chainId: CHAIN_ID,
245	      };
246	      if (asset === "USDC") response.tokenAddress = config.usdcMockAddress;
247	      reply.status(200).send(response);
248	    },
249	  );
250	
251	  return app;
252	}
