 22	function positiveInt(name: string, raw: string | undefined, fallback?: number): number {
 23	  if (raw === undefined && fallback !== undefined) return fallback;
 24	  if (raw === undefined || !/^[1-9][0-9]*$/.test(raw)) {
 25	    throw new Error(`INTERNAL_ERROR: ${name} debe ser un entero positivo`);
 26	  }
 27	  const value = Number(raw);
 28	  if (!Number.isSafeInteger(value)) {
 29	    throw new Error(`INTERNAL_ERROR: ${name} está fuera de rango`);
 30	  }
 31	  return value;
 32	}
 33	
 34	function encryptionKey(raw: string | undefined): Buffer {
 35	  if (!raw) throw new Error("INTERNAL_ERROR: falta WALLET_ENCRYPTION_KEY");
 36	  const value = raw.startsWith("base64:")
 37	    ? Buffer.from(raw.slice(7), "base64")
 38	    : Buffer.from(raw, "hex");
 39	  if (value.length !== 32) {
 40	    throw new Error("INTERNAL_ERROR: WALLET_ENCRYPTION_KEY debe contener exactamente 32 bytes");
 41	  }
 42	  return value;
 43	}
 44	
 45	function optionalRateLimit(
 46	  env: NodeJS.ProcessEnv,
 47	  maxName: string,
 48	  windowName: string,
 49	): RateLimitConfig | undefined {
 50	  const max = env[maxName];
 51	  const window = env[windowName];
 52	  if (max === undefined && window === undefined) return undefined;
 53	  if (max === undefined || window === undefined) {
 54	    throw new Error(`INTERNAL_ERROR: ${maxName} y ${windowName} deben configurarse juntos`);
 55	  }
 56	  return { max: positiveInt(maxName, max), windowSeconds: positiveInt(windowName, window) };
 57	}
