 61	  if (ttl < 60 || ttl > 86_400) {
 62	    throw new Error("INTERNAL_ERROR: SESSION_TTL_SECONDS debe estar entre 60 y 86400");
 63	  }
 64	
 65	  if (!env.USDC_MOCK_ADDRESS) {
 66	    throw new Error("INTERNAL_ERROR: falta USDC_MOCK_ADDRESS");
 67	  }
 68	  let usdcMockAddress: string;
