 70	    usdcMockAddress = getAddress(env.USDC_MOCK_ADDRESS);
 71	  } catch {
 72	    throw new Error("INTERNAL_ERROR: USDC_MOCK_ADDRESS no es una dirección Ethereum válida");
 73	  }
