  3	interface Entry {
  4	  timestamps: number[];
  5	}
  6	
  7	export class SlidingWindowRateLimiter {
  8	  private readonly entries = new Map<string, Entry>();
  9	
 10	  check(key: string, config: RateLimitConfig, now = Date.now()): { limited: boolean; retryAfterSeconds: number } {
 11	    const windowMs = config.windowSeconds * 1000;
 12	    const cutoff = now - windowMs;
 13	    const entry = this.entries.get(key) ?? { timestamps: [] };
 14	    entry.timestamps = entry.timestamps.filter((timestamp) => timestamp > cutoff);
 15	    if (entry.timestamps.length >= config.max) {
 16	      const oldest = entry.timestamps[0] ?? now;
 17	      return {
 18	        limited: true,
 19	        retryAfterSeconds: Math.max(0, Math.ceil((oldest + windowMs - now) / 1000)),
 20	      };
 21	    }
 22	    entry.timestamps.push(now);
 23	    this.entries.set(key, entry);
 24	    return { limited: false, retryAfterSeconds: 0 };
 25	  }
 26	}

