    for (let index = 0; index < 4; index += 1) await register(app, `seed-${index}@example.com`);
    const accountId = randomUUID();
    app.exchangeStore.db.prepare(
      `INSERT INTO accounts (account_id, email, password_hash, status, created_at)
       VALUES (?, ?, 'hash-interno-no-utilizado', 'ACTIVE', ?)`,
    ).run(accountId, "skipped@example.com", new Date().toISOString());
    const curveOrder = Buffer.from(
      "fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141",
      "hex",
    );
    const hmac = (key: Uint8Array, data: Uint8Array) => {
      const input = Buffer.from(data);
      const index = input.length >= 4 ? input.readUInt32BE(input.length - 4) : -1;
      if (input.length === 37 && index === 4) return Buffer.concat([curveOrder, Buffer.alloc(32)]);
      return createHmac("sha512", key).update(data).digest();
    };
    const service = new WalletService(app.exchangeStore, hmac);
    const assigned = service.getOrAssign(accountId);
    expect(assigned.address_index).toBe(5);
    const skipped = app.exchangeStore.db.prepare(
      "SELECT address_index, reason FROM skipped_address_indices",
    ).get() as { address_index: number; reason: string };
