  it("genera mnemonics BIP-39 válidos de 24 palabras y distintos", () => {
    const first = generateProjectSeed();
    const second = generateProjectSeed();
    expect(first.mnemonic.split(" ")).toHaveLength(24);
    expect(validateProjectMnemonic(first.mnemonic)).toBe(first.mnemonic);
    expect(first.seed).toHaveLength(64);
    expect(second.mnemonic).not.toBe(first.mnemonic);
    expect(second.seed.equals(first.seed)).toBe(false);
  });

  it("rechaza mnemonics válidos de longitud no permitida para provisioning", () => {
    expect(() => validateProjectMnemonic(BIP39_MNEMONIC)).toThrowError(
