    expect(first).not.toEqual(second);
    expect(decryptSeed(first, key)).toEqual(seed);
    expect(() => decryptSeed(first, randomBytes(32))).toThrow();
    first[first.length - 1]! ^= 1;
    expect(() => decryptSeed(first, key)).toThrow();
  });

  it("cumple los vectores BIP-44/Ethereum de Hardhat", () => {
    const seed = mnemonicToSeed(HARDHAT_MNEMONIC);
    const expected = [
      "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266",
      "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
      "0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC",
      "0x90F79bf6EB2c4f870365E785982E1f101E93b906",
    ];
    expected.forEach((address, index) => {
      const derived = deriveAddress(seed, index);
      expect(derived.address).toBe(address);
      expect(derived.derivationPath).toBe(`m/44'/60'/0'/0/${index}`);
      expect(derived.publicKey).toMatch(/^0x04[0-9a-fA-F]{128}$/);
    });
  });

  it("cumple los vectores de checksum EIP-55", () => {
    const vectors = [
      ["5aaeb6053f3e94c9b9a09f33669435e7ef1beaed", "0x5aAeb6053F3E94C9b9A09f33669435E7Ef1BeAed"],
      ["fb6916095ca1df60bb79ce92ce3ea74c37c5d359", "0xfB6916095ca1df60bB79Ce92cE3Ea74c37c5d359"],
      ["dbf03b407c01e7cd3cbea99509d93f8dddc8c6fb", "0xdbF03B407c01E7cD3CBea99509d93f8DDDC8C6FB"],
      ["d1220a0cf47c7b9be7a2e6ba89f429762e7b9adb", "0xD1220A0cf47c7B9Be7A2E6BA89F429762e7b9aDb"],
    ];
    for (const [raw, checksummed] of vectors) expect(toChecksumAddress(raw!)).toBe(checksummed);
  });

  it("valida el rango no-hardened y salta una clave hija inválida de modo determinista", () => {
    const seed = mnemonicToSeed(HARDHAT_MNEMONIC);
    expect(() => deriveAddress(seed, 2 ** 31)).toThrowError(/VALIDATION_ERROR|solicitud/i);
    expect(deriveAddress(seed, 2 ** 31 - 1).address).toMatch(/^0x[0-9a-fA-F]{40}$/);
    const curveOrder = Buffer.from(
      "fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141",
      "hex",
    );
    const injectedHmac = (key: Uint8Array, data: Uint8Array) => {
      const input = Buffer.from(data);
      const index = input.length >= 4 ? input.readUInt32BE(input.length - 4) : -1;
      if (input.length === 37 && index === 4) {
        return Buffer.concat([curveOrder, Buffer.alloc(32)]);
      }
      return createHmac("sha512", key).update(data).digest();
    };
    const result = deriveNextValidAddress(seed, 4, injectedHmac);
    expect(result.addressIndex).toBe(5);
    expect(result.skippedIndices).toEqual([4]);
    expect(result.address).toBe(deriveAddress(seed, 5).address);
    expect(BIP44_ETHEREUM_PREFIX).toEqual([2147483692, 2147483708, 2147483648, 0]);
  });
});

import {
  createCipheriv,
  createDecipheriv,
  createHmac,
  pbkdf2Sync,
  randomBytes,
} from "node:crypto";
import { Mnemonic, SigningKey, getAddress, keccak256, wordlists } from "ethers";
import { ApiError, validationError } from "../errors.js";

export const CHAIN_ID = "11155111";
export const NETWORK = "sepolia";
export const MAX_ADDRESS_INDEX = 2 ** 31 - 1;
export const HARDENED_OFFSET = 2 ** 31;
export const BIP44_ETHEREUM_PREFIX = [
  44 + HARDENED_OFFSET,
  60 + HARDENED_OFFSET,
  HARDENED_OFFSET,
  0,
] as const;
const SECP256K1_N = BigInt("0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141");

export type HmacSha512 = (key: Uint8Array, data: Uint8Array) => Uint8Array;

export interface DerivedAddress {
  addressIndex: number;
  address: string;
  derivationPath: string;
  publicKey: string;
  skippedIndices?: number[];
}

export class InvalidDerivedKeyError extends Error {}

function defaultHmacSha512(key: Uint8Array, data: Uint8Array): Uint8Array {
  return createHmac("sha512", key).update(data).digest();
}

function parse256(value: Uint8Array): bigint {
  return BigInt(`0x${Buffer.from(value).toString("hex")}`);
}

function serialize256(value: bigint): Buffer {
  return Buffer.from(value.toString(16).padStart(64, "0"), "hex");
}

function serialize32(value: number): Buffer {
  const result = Buffer.allocUnsafe(4);
  result.writeUInt32BE(value, 0);
  return result;
}

interface ExtendedPrivateKey {
  privateKey: Buffer;
  chainCode: Buffer;
}

function masterKey(seed: Uint8Array, hmac: HmacSha512): ExtendedPrivateKey {
  const digest = Buffer.from(hmac(Buffer.from("Bitcoin seed", "utf8"), seed));
  if (digest.length !== 64) throw new Error("Salida HMAC-SHA512 inválida");
  const privateKey = digest.subarray(0, 32);
  const keyNumber = parse256(privateKey);
  if (keyNumber < 1n || keyNumber >= SECP256K1_N) {
    throw new Error("Seed BIP-32 produjo una clave maestra inválida");
  }
  return { privateKey: Buffer.from(privateKey), chainCode: Buffer.from(digest.subarray(32)) };
}

function deriveChild(parent: ExtendedPrivateKey, index: number, hmac: HmacSha512): ExtendedPrivateKey {
  const indexBytes = serialize32(index);
  const data = index >= HARDENED_OFFSET
    ? Buffer.concat([Buffer.from([0]), parent.privateKey, indexBytes])
    : Buffer.concat([
        Buffer.from(SigningKey.computePublicKey(parent.privateKey, true).slice(2), "hex"),
        indexBytes,
      ]);
  const digest = Buffer.from(hmac(parent.chainCode, data));
  if (digest.length !== 64) throw new Error("Salida HMAC-SHA512 inválida");
  const left = parse256(digest.subarray(0, 32));
  if (left >= SECP256K1_N) throw new InvalidDerivedKeyError("I_L está fuera de secp256k1");
  const childNumber = (left + parse256(parent.privateKey)) % SECP256K1_N;
  if (childNumber === 0n) throw new InvalidDerivedKeyError("La clave hija BIP-32 es cero");
  return {
    privateKey: serialize256(childNumber),
    chainCode: Buffer.from(digest.subarray(32)),
  };
}

export function normalizeMnemonic(value: string): string {
  return value.normalize("NFKD").trim().replace(/\s+/g, " ");
}

export function validateProjectMnemonic(value: string): string {
  const normalized = normalizeMnemonic(value);
  if (normalized.split(" ").length !== 24) {
    throw validationError([{ field: "mnemonic", message: "Debe contener exactamente 24 palabras" }]);
  }
  if (!Mnemonic.isValidMnemonic(normalized, wordlists.en)) {
    throw validationError([{ field: "mnemonic", message: "Wordlist o checksum BIP-39 inválido" }]);
  }
  return normalized;
}

export function mnemonicToSeed(mnemonic: string, passphrase = ""): Buffer {
  const normalizedMnemonic = normalizeMnemonic(mnemonic);
  const normalizedPassphrase = passphrase.normalize("NFKD");
  return pbkdf2Sync(
    normalizedMnemonic,
    `mnemonic${normalizedPassphrase}`,
    2048,
    64,
    "sha512",
  );
}

export function generateProjectSeed(passphrase = ""): { mnemonic: string; seed: Buffer } {
  const mnemonic = Mnemonic.fromEntropy(randomBytes(32), "", wordlists.en).phrase;
  return { mnemonic, seed: mnemonicToSeed(mnemonic, passphrase) };
}

export function toChecksumAddress(rawAddress: string): string {
  const prefixed = rawAddress.startsWith("0x") ? rawAddress : `0x${rawAddress}`;
  return getAddress(prefixed.toLowerCase());
}

export function encryptSeed(seed: Buffer, key: Buffer): Buffer {
  if (key.length !== 32) throw new Error("La clave AES debe tener 32 bytes");
  const nonce = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", key, nonce, { authTagLength: 16 });
  const ciphertext = Buffer.concat([cipher.update(seed), cipher.final()]);
  return Buffer.concat([nonce, ciphertext, cipher.getAuthTag()]);
}

export function decryptSeed(payload: Buffer, key: Buffer): Buffer {
  if (payload.length < 29 || key.length !== 32) throw new Error("Seed cifrado inválido");
  const nonce = payload.subarray(0, 12);
  const tag = payload.subarray(payload.length - 16);
  const ciphertext = payload.subarray(12, payload.length - 16);
  const decipher = createDecipheriv("aes-256-gcm", key, nonce, { authTagLength: 16 });
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

export function deriveAddress(
  seed: Uint8Array,
  addressIndex: number,
  hmac: HmacSha512 = defaultHmacSha512,
): DerivedAddress {
  if (!Number.isSafeInteger(addressIndex) || addressIndex < 0 || addressIndex > MAX_ADDRESS_INDEX) {
    throw validationError([
      { field: "address_index", message: `Debe estar entre 0 y ${MAX_ADDRESS_INDEX}` },
    ]);
  }
  const derivationPath = `m/44'/60'/0'/0/${addressIndex}`;
  let extended = masterKey(seed, hmac);
  for (const index of [...BIP44_ETHEREUM_PREFIX, addressIndex]) {
    extended = deriveChild(extended, index, hmac);
  }
  const publicKey = SigningKey.computePublicKey(extended.privateKey, false);
  // Ethereum hashea X || Y (64 bytes), sin el byte SEC1 0x04.
  const publicKeyBytes = Buffer.from(publicKey.slice(4), "hex");
  const rawAddress = keccak256(publicKeyBytes).slice(-40);
  return {
    addressIndex,
    address: toChecksumAddress(rawAddress),
    derivationPath,
    publicKey,
  };
}

export function deriveNextValidAddress(
  seed: Uint8Array,
  startIndex: number,
  hmac: HmacSha512 = defaultHmacSha512,
): DerivedAddress {
  const skippedIndices: number[] = [];
  for (let index = startIndex; index <= MAX_ADDRESS_INDEX; index += 1) {
    try {
      const result = deriveAddress(seed, index, hmac);
      return skippedIndices.length === 0 ? result : { ...result, skippedIndices };
    } catch (error) {
      if (!(error instanceof InvalidDerivedKeyError)) throw error;
      skippedIndices.push(index);
    }
  }
  throw new ApiError("INTERNAL_ERROR");
}
import { createHash, randomBytes, randomUUID } from "node:crypto";
import type { Store, AccountRow } from "../database.js";
import { ApiError } from "../errors.js";
import { hashPassword, verifyAgainstDummy, verifyPassword } from "../crypto/password.js";
import type { WalletService } from "./wallet-service.js";

export interface PublicAccount {
  accountId: string;
  email: string;
  status: "ACTIVE";
  createdAt: string;
}

export interface LoginResult {
  token: string;
  expiresAt: string;
}

function publicAccount(row: AccountRow): PublicAccount {
  return {
    accountId: row.account_id,
    email: row.email,
    status: row.status,
    createdAt: row.created_at,
  };
}

function tokenHash(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}

export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

export class AuthService {
  constructor(
    private readonly store: Store,
    private readonly walletService: WalletService,
  ) {}

  async register(email: string, password: string): Promise<PublicAccount> {
    const normalizedEmail = normalizeEmail(email);
    const passwordHash = await hashPassword(password);
    const account: AccountRow = {
      account_id: randomUUID(),
      email: normalizedEmail,
      password_hash: passwordHash,
      status: "ACTIVE",
      created_at: new Date().toISOString(),
    };
    try {
      this.store.transaction(() => {
        this.store.db.prepare(
          `INSERT INTO accounts (account_id, email, password_hash, status, created_at)
           VALUES (?, ?, ?, ?, ?)`,
        ).run(
          account.account_id,
          account.email,
          account.password_hash,
          account.status,
          account.created_at,
        );
        this.walletService.assignInsideTransaction(account.account_id);
      });
    } catch (error) {
      if (error instanceof Error && /UNIQUE constraint failed: accounts\.email/.test(error.message)) {
        throw new ApiError("EMAIL_ALREADY_EXISTS", { email: normalizedEmail });
      }
      throw error;
    }
    return publicAccount(account);
  }

  async login(email: string, password: string, origin?: string): Promise<LoginResult> {
    const normalizedEmail = normalizeEmail(email);
    const account = this.store.findAccountByEmail(normalizedEmail);
    let valid = false;
    if (account) {
      valid = await verifyPassword(password, account.password_hash);
    } else {
      await verifyAgainstDummy(password);
    }

    if (!account || !valid) {
      this.audit(normalizedEmail, "FAILURE", "INVALID_CREDENTIALS", origin);
      throw new ApiError("INVALID_CREDENTIALS");
    }

    const token = randomBytes(32).toString("base64url");
    const now = new Date();
    const expiresAt = new Date(now.getTime() + this.store.config.sessionTtlSeconds * 1000).toISOString();
    this.store.db.prepare(
      "INSERT INTO sessions (token_hash, account_id, expires_at, created_at) VALUES (?, ?, ?, ?)",
    ).run(tokenHash(token), account.account_id, expiresAt, now.toISOString());
    this.audit(normalizedEmail, "SUCCESS", undefined, origin);
    return { token, expiresAt };
  }

  authenticate(token: string): AccountRow | undefined {
    const session = this.store.db.prepare(
      `SELECT a.account_id, a.email, a.password_hash, a.status, a.created_at, s.expires_at
       FROM sessions s JOIN accounts a ON a.account_id = s.account_id
       WHERE s.token_hash = ?`,
    ).get(tokenHash(token)) as (AccountRow & { expires_at: string }) | undefined;
    if (!session || Date.parse(session.expires_at) <= Date.now()) return undefined;
    return session;
  }

  auditRateLimited(email: string, origin?: string): void {
    this.audit(normalizeEmail(email), "FAILURE", "RATE_LIMITED", origin);
  }

  private audit(
    email: string,
    result: "SUCCESS" | "FAILURE",
    reason?: string,
    origin?: string,
  ): void {
    this.store.db.prepare(
      `INSERT INTO auth_audit (timestamp, email, result, reason, origin)
       VALUES (?, ?, ?, ?, ?)`,
    ).run(new Date().toISOString(), email, result, reason ?? null, origin ?? null);
  }
}
import { randomUUID } from "node:crypto";
import type { Store, AddressRow } from "../database.js";
import { addressRecord } from "../database.js";
import { ApiError } from "../errors.js";
import { CHAIN_ID, deriveNextValidAddress, type HmacSha512 } from "../crypto/wallet.js";

export interface DepositAddressAssignedEvent {
  eventId: string;
  accountId: string;
  payload: {
    accountId: string;
    addressIndex: number;
    address: string;
    chainId: "11155111";
  };
  occurredAt: string;
}

export class WalletService {
  constructor(
    private readonly store: Store,
    private readonly hmac?: HmacSha512,
  ) {}

  getOrAssign(accountId: string): AddressRow {
    const existing = this.store.findAddress(accountId);
    if (existing) return existing;
    if (!this.store.findAccountById(accountId)) {
      throw new ApiError("ACCOUNT_NOT_FOUND", { accountId });
    }
    return this.store.transaction(() => this.assignInsideTransaction(accountId));
  }

  assignInsideTransaction(accountId: string): AddressRow {
    const existing = this.store.findAddress(accountId);
    if (existing) return existing;
    const maxRow = this.store.db.prepare(
      "SELECT MAX(address_index) AS max_index FROM deposit_addresses",
    ).get() as { max_index: number | null };
    const nextIndex = maxRow.max_index === null ? 0 : maxRow.max_index + 1;
    const derived = this.hmac
      ? deriveNextValidAddress(this.store.seed, nextIndex, this.hmac)
      : deriveNextValidAddress(this.store.seed, nextIndex);
    const createdAt = new Date().toISOString();
    for (const skippedIndex of derived.skippedIndices ?? []) {
      this.store.db.prepare(
        `INSERT INTO skipped_address_indices (address_index, reason, occurred_at)
         VALUES (?, 'INVALID_BIP32_CHILD', ?)`,
      ).run(skippedIndex, createdAt);
    }
    const row = addressRecord(
      accountId,
      derived.addressIndex,
      derived.address,
      derived.derivationPath,
      createdAt,
    );
    this.store.db.prepare(
      `INSERT INTO deposit_addresses
       (account_id, address_index, address, derivation_path, network, chain_id, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      row.account_id,
      row.address_index,
      row.address,
      row.derivation_path,
      row.network,
      row.chain_id,
      row.created_at,
    );
    this.store.db.prepare(
      `INSERT INTO domain_events
       (event_id, event_type, account_id, payload, occurred_at)
       VALUES (?, 'DepositAddressAssigned', ?, ?, ?)`,
    ).run(
      randomUUID(),
      accountId,
      JSON.stringify({
        accountId,
        addressIndex: row.address_index,
        address: row.address,
        chainId: CHAIN_ID,
      }),
      createdAt,
    );
    return row;
  }

  listAssigned(): AddressRow[] {
    return this.store.getAssignedAddresses();
  }

  listAssignedEvents(): DepositAddressAssignedEvent[] {
    const rows = this.store.db.prepare(
      `SELECT event_id, account_id, payload, occurred_at
       FROM domain_events WHERE event_type = 'DepositAddressAssigned' ORDER BY occurred_at, event_id`,
    ).all() as unknown as Array<{
      event_id: string;
      account_id: string;
      payload: string;
      occurred_at: string;
    }>;
    return rows.map((row) => ({
      eventId: row.event_id,
      accountId: row.account_id,
      payload: JSON.parse(row.payload) as DepositAddressAssignedEvent["payload"],
      occurredAt: row.occurred_at,
    }));
  }
}

