import { randomBytes } from "node:crypto";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { FastifyInstance } from "fastify";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { buildApp } from "../src/app.js";
import type { AppConfig } from "../src/config.js";

const USDC_ADDRESS = "0x5aAeb6053F3E94C9b9A09f33669435E7Ef1BeAed";

interface AuditRow {
  timestamp: string;
  email: string;
  result: "SUCCESS" | "FAILURE";
  reason: string | null;
  origin: string | null;
}

function makeConfig(databasePath: string): AppConfig {
  return {
    host: "127.0.0.1",
    port: 3000,
    databasePath,
    sessionTtlSeconds: 3600,
    walletEncryptionKey: randomBytes(32),
    usdcMockAddress: USDC_ADDRESS,
    sepoliaRpcUrl: "http://127.0.0.1:8545",
    hdMnemonicPassphrase: "",
  };
}

function auditRows(app: FastifyInstance): AuditRow[] {
  return app.exchangeStore.db.prepare(
    `SELECT timestamp, email, result, reason, origin
     FROM auth_audit ORDER BY audit_id ASC`,
  ).all() as unknown as AuditRow[];
}

describe("auditoría completa de POST /api/v1/auth/login", () => {
  let directory: string;
  let config: AppConfig;
  let app: FastifyInstance;

  beforeEach(async () => {
    directory = mkdtempSync(join(tmpdir(), "exchange-login-audit-test-"));
    config = makeConfig(join(directory, "exchange.sqlite"));
    app = await buildApp(config);
  });

  afterEach(async () => {
    await app.close();
    rmSync(directory, { recursive: true, force: true });
  });

  it("registra una sola fila para éxito y para cada desenlace fallido, incluso antes del handler", async () => {
    const registration = await app.inject({
      method: "POST",
      url: "/api/v1/auth/register",
      headers: { "content-type": "application/json" },
      payload: { email: "trader@example.com", password: "Sup3rSecreta" },
    });
    expect(registration.statusCode).toBe(201);

    const requests = [
      app.inject({
        method: "POST",
        url: "/api/v1/auth/login",
        headers: { "content-type": "application/json" },
        payload: { email: "  TRADER@Example.com ", password: "Sup3rSecreta" },
      }),
      app.inject({
        method: "POST",
        url: "/api/v1/auth/login",
        headers: { "content-type": "application/json" },
        payload: { email: "  TRADER@Example.com ", password: "incorrecta" },
      }),
      app.inject({
        method: "POST",
        url: "/api/v1/auth/login",
        headers: { "content-type": "application/json" },
        payload: { email: "  SCHEMA@Example.com " },
      }),
      app.inject({
        method: "POST",
        url: "/api/v1/auth/login",
        headers: { "content-type": "application/json" },
        payload: { email: 123, password: "incorrecta" },
      }),
      app.inject({
        method: "POST",
        url: "/api/v1/auth/login",
        headers: { "content-type": "application/json" },
        payload: "{malformed",
      }),
      app.inject({
        method: "POST",
        url: "/api/v1/auth/login",
        headers: { "content-type": "text/plain" },
        payload: "not-json",
      }),
      app.inject({
        method: "POST",
        url: "/api/v1/auth/login",
        headers: { "content-type": "application/json" },
        payload: { email: "large@example.com", password: "x".repeat(1_100_000) },
      }),
    ];
    const responses = await Promise.all(requests);
    expect(responses.map((response) => response.statusCode)).toEqual([200, 401, 422, 422, 422, 422, 422]);
    expect(responses.slice(2).map((response) => response.json().error.code)).toEqual([
      "VALIDATION_ERROR",
      "VALIDATION_ERROR",
      "VALIDATION_ERROR",
      "VALIDATION_ERROR",
      "VALIDATION_ERROR",
    ]);

    vi.spyOn(app.authService, "login").mockRejectedValueOnce(new Error("detalle interno sensible"));
    const internal = await app.inject({
      method: "POST",
      url: "/api/v1/auth/login",
      headers: { "content-type": "application/json" },
      payload: { email: " INTERNAL@Example.com ", password: "Sup3rSecreta" },
    });
    expect(internal.statusCode).toBe(500);
    expect(internal.json()).toEqual({
      error: { code: "INTERNAL_ERROR", message: expect.any(String) },
    });
    expect(internal.body).not.toContain("detalle interno sensible");

    const rows = auditRows(app);
    const outcomes = rows.map(({ email, result, reason }) => ({ email, result, reason }));
    expect(rows).toHaveLength(8);
    expect(outcomes).toEqual(expect.arrayContaining([
      { email: "trader@example.com", result: "SUCCESS", reason: null },
      { email: "trader@example.com", result: "FAILURE", reason: "INVALID_CREDENTIALS" },
      { email: "schema@example.com", result: "FAILURE", reason: "VALIDATION_ERROR" },
      { email: "internal@example.com", result: "FAILURE", reason: "INTERNAL_ERROR" },
    ]));
    expect(outcomes.filter(({ email, reason }) => email === "" && reason === "VALIDATION_ERROR")).toHaveLength(4);
    for (const row of rows) {
      expect(new Date(row.timestamp).toISOString()).toBe(row.timestamp);
      expect(row.origin).toBe("127.0.0.1");
    }
  });

  it("audita RATE_LIMITED aunque el JSON no llegue a parsearse", async () => {
    await app.close();
    app = await buildApp({
      ...config,
      databasePath: join(directory, "rate-limited.sqlite"),
      loginRateLimit: { max: 1, windowSeconds: 60 },
    });

    const malformed = {
      method: "POST" as const,
      url: "/api/v1/auth/login",
      headers: { "content-type": "application/json" },
      payload: "{malformed",
    };
    const first = await app.inject(malformed);
    const limited = await app.inject(malformed);
    expect(first.statusCode).toBe(422);
    expect(first.json().error.code).toBe("VALIDATION_ERROR");
    expect(limited.statusCode).toBe(429);
    expect(limited.json().error).toMatchObject({
      code: "RATE_LIMITED",
      details: { retryAfterSeconds: expect.any(Number) },
    });
    expect(limited.headers["retry-after"]).toBeDefined();

    expect(auditRows(app).map(({ email, result, reason }) => ({ email, result, reason }))).toEqual([
      { email: "", result: "FAILURE", reason: "VALIDATION_ERROR" },
      { email: "", result: "FAILURE", reason: "RATE_LIMITED" },
    ]);
  });
});
